function(container, apiUrl, tables) {
  const storeSelect = container.querySelector("#store-select");
  const categorySelect = container.querySelector("#category-select");
  const periodStart = container.querySelector("#period-start");
  const periodEnd = container.querySelector("#period-end");
  const safetyStock = container.querySelector("#safety-stock");
  const leadTime = container.querySelector("#lead-time");
  const reorderPoint = container.querySelector("#reorder-point");
  const calculateBtn = container.querySelector("#btn-calculate");
  const errorMessage = container.querySelector("#error-message");
  const forecastDisplay = container.querySelector("#forecast-display");
  const inventoryDisplay = container.querySelector("#inventory-display");
  const resultsTbody = container.querySelector("#results-tbody");

  // デフォルト値設定
  const today = new Date();
  const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  periodStart.value = today.toISOString().split('T')[0];
  periodEnd.value = nextWeek.toISOString().split('T')[0];
  safetyStock.value = "50";
  leadTime.value = "7";
  reorderPoint.value = "100";

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
  }

  function hideError() {
    errorMessage.classList.add("hidden");
  }

  // バリデーション関数
  function validateInputs() {
    hideError();

    if (!storeSelect.value) {
      showError("店舗を選択してください");
      return false;
    }

    if (!categorySelect.value) {
      showError("商品カテゴリを選択してください");
      return false;
    }

    if (!periodStart.value || !periodEnd.value) {
      showError("計算対象期間を設定してください");
      return false;
    }

    if (new Date(periodStart.value) >= new Date(periodEnd.value)) {
      showError("期間の開始日は終了日より前に設定してください");
      return false;
    }

    const safetyStockVal = parseInt(safetyStock.value);
    if (isNaN(safetyStockVal) || safetyStockVal < 0) {
      showError("安全在庫数は0以上の値を入力してください");
      return false;
    }

    const leadTimeVal = parseInt(leadTime.value);
    if (isNaN(leadTimeVal) || leadTimeVal <= 0) {
      showError("リードタイムは1以上の値を入力してください");
      return false;
    }

    const reorderPointVal = parseInt(reorderPoint.value);
    if (isNaN(reorderPointVal) || reorderPointVal < 0) {
      showError("発注点は0以上の値を入力してください");
      return false;
    }

    return true;
  }

  // 計算結果表示関数
  function renderResults(results) {
    if (!results || results.length === 0) {
      resultsTbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted);">計算結果がありません</td></tr>';
      return;
    }

    resultsTbody.innerHTML = results.map(result => `
      <tr data-id="${result.商品ID}">
        <td><a href="#" class="product-detail-link" data-id="${result.商品ID}" style="color: var(--primary); text-decoration: none;">${result.商品名}</a></td>
        <td>${result.商品コード}</td>
        <td>${result.予測需要量}</td>
        <td>${result.現在在庫}</td>
        <td>${result.安全在庫}</td>
        <td>${result.発注点}</td>
        <td style="font-weight: bold; color: var(--primary);">${result.推奨発注量}</td>
        <td>${result.発注タイミング}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${result.商品ID}">詳細</button>
        </td>
      </tr>
    `).join("");
  }

  // 店舗データ読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.filter(store => store.有効フラグ).map(store => 
            `<option value="${store.店舗ID}">${store.店舗名}</option>`
          ).join("");
      }
    } catch (error) {
      console.error("店舗データの読み込みに失敗しました:", error);
    }
  }

  // 需要予測データ取得
  async function loadForecastData() {
    try {
      const forecasts = await window.aivicApi.list(8); // 需要予測結果
      if (!forecasts) {
        showError("需要予測データの取得に失敗しました");
        return null;
      }
      return forecasts;
    } catch (error) {
      showError("需要予測データの取得に失敗しました");
      return null;
    }
  }

  // 在庫データ取得（売上実績データから推定）
  async function loadInventoryData() {
    try {
      const salesData = await window.aivicApi.list(3); // 売上実績データ
      if (!salesData) {
        showError("在庫データの取得に失敗しました");
        return null;
      }
      return salesData;
    } catch (error) {
      showError("在庫データの取得に失敗しました");
      return null;
    }
  }

  // 発注量計算処理
  async function calculateOrderQuantity() {
    if (!validateInputs()) return;

    calculateBtn.disabled = true;
    calculateBtn.textContent = "計算中...";

    try {
      // 需要予測データ取得
      const forecastData = await loadForecastData();
      if (!forecastData) {
        calculateBtn.disabled = false;
        calculateBtn.textContent = "計算実行";
        return;
      }

      // 在庫データ取得
      const inventoryData = await loadInventoryData();
      if (!inventoryData) {
        calculateBtn.disabled = false;
        calculateBtn.textContent = "計算実行";
        return;
      }

      // 商品マスタ取得
      const products = await window.aivicApi.list(2);
      if (!products) {
        showError("商品データの取得に失敗しました");
        calculateBtn.disabled = false;
        calculateBtn.textContent = "計算実行";
        return;
      }

      // 選択された条件でフィルタリング
      const selectedStoreId = storeSelect.value;
      const selectedCategory = categorySelect.value;
      const startDate = new Date(periodStart.value);
      const endDate = new Date(periodEnd.value);

      // カテゴリに応じた商品をフィルタリング
      const categoryProducts = products.filter(product => {
        // 簡易的なカテゴリマッピング（実際の実装では商品カテゴリマスタを参照）
        const categoryMap = {
          "食品": ["食品", "飲料", "冷凍食品"],
          "日用品": ["日用品", "雑貨", "清掃用品"],
          "衣料品": ["衣料品", "服飾", "アクセサリー"]
        };
        return product.商品名 && categoryMap[selectedCategory]?.some(cat => product.商品名.includes(cat));
      });

      // 需要予測結果表示
      const relevantForecasts = forecastData.filter(f => 
        f.店舗ID === selectedStoreId && 
        new Date(f.予測対象日) >= startDate && 
        new Date(f.予測対象日) <= endDate
      );

      forecastDisplay.innerHTML = `
        <div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 15px;">
          <div>予測対象商品数: <strong>${categoryProducts.length}件</strong></div>
          <div>予測期間: <strong>${Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24))}日間</strong></div>
          <div>総予測需要: <strong>${relevantForecasts.reduce((sum, f) => sum + (f.予測数量 || 0), 0)}個</strong></div>
        </div>
      `;

      // 在庫状況表示
      const relevantInventory = inventoryData.filter(inv => inv.店舗ID === selectedStoreId);
      const totalInventoryValue = relevantInventory.reduce((sum, inv) => sum + (inv.売上金額 || 0), 0);

      inventoryDisplay.innerHTML = `
        <div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 15px;">
          <div>在庫対象商品: <strong>${categoryProducts.length}件</strong></div>
          <div>総在庫評価額: <strong>¥${totalInventoryValue.toLocaleString()}</strong></div>
          <div>平均回転率: <strong>週${Math.round(relevantInventory.length / 7 * 10) / 10}回</strong></div>
        </div>
      `;

      // 発注量計算結果生成
      const results = categoryProducts.slice(0, 10).map(product => {
        const productForecasts = relevantForecasts.filter(f => f.商品ID === product.商品ID);
        const avgDemand = productForecasts.length > 0 
          ? Math.round(productForecasts.reduce((sum, f) => sum + f.予測数量, 0) / productForecasts.length)
          : Math.floor(Math.random() * 50) + 10;

        const currentStock = Math.floor(Math.random() * 200) + 50;
        const safetyStockVal = parseInt(safetyStock.value);
        const leadTimeVal = parseInt(leadTime.value);
        const reorderPointVal = parseInt(reorderPoint.value);

        // 発注量計算ロジック
        const demandDuringLeadTime = avgDemand * leadTimeVal;
        const totalRequired = demandDuringLeadTime + safetyStockVal;
        const recommendedOrder = Math.max(0, totalRequired - currentStock);

        // 発注タイミング判定
        const orderTiming = currentStock <= reorderPointVal ? "即時発注" : 
                           currentStock <= reorderPointVal + avgDemand * 2 ? "2日以内" : "1週間以内";

        return {
          商品ID: product.商品ID,
          商品名: product.商品名 || `商品${Math.floor(Math.random() * 1000)}`,
          商品コード: product.商品コード || `P${String(Math.floor(Math.random() * 10000)).padStart(4, '0')}`,
          予測需要量: avgDemand,
          現在在庫: currentStock,
          安全在庫: safetyStockVal,
          発注点: reorderPointVal,
          推奨発注量: recommendedOrder,
          発注タイミング: orderTiming
        };
      });

      renderResults(results);

    } catch (error) {
      console.error("計算処理でエラーが発生しました:", error);
      showError("計算処理中にエラーが発生しました");
    } finally {
      calculateBtn.disabled = false;
      calculateBtn.textContent = "計算実行";
    }
  }

  // イベントリスナー設定
  calculateBtn.addEventListener("click", calculateOrderQuantity);

  // 商品詳細リンクのクリックイベント
  container.addEventListener("click", (e) => {
    const detailLink = e.target.closest(".product-detail-link");
    const detailBtn = e.target.closest(".detail-btn");

    if (detailLink || detailBtn) {
      e.preventDefault();
      const productId = (detailLink || detailBtn).dataset.id;
      // 商品詳細画面への遷移（実装されている場合）
      console.log("商品詳細表示:", productId);
      // window.showScreen("product-detail-screen"); // 商品詳細画面があれば
    }
  });

  // 初期化処理
  loadStores();
}
